mod solution;

fn valid(_input: &str, actual: &str, expected: &str) -> bool { actual == expected }

fn main() {
    let cases = [
        ("n=5 updates=(0,2,2),(1,3,3),(3,4,1)","5"),
        ("n=4 updates=(0,1,2),(1,3,1)","3"),
        ("n=4 updates=(0,1,2),(2,3,2)","2"),
        ("n=3 updates=(0,2,1),(0,2,4)","5"),
        ("n=5 updates=(4,4,9),(0,0,2)","9"),
        ("  \nn=5 updates=(0,2,2),(1,3,3),(3,4,1)\n  ","5"),
        ("\nn=5 updates=(4,4,9),(0,0,2)\n","9")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS imos-sweep");
}
